/**
 * @fileoverview Code-owned semantic surface-role extremes for quality gates.
 *
 * These are deliberately complete material hierarchies. A torture tenant is
 * useful only when every component family is forced to resolve the same eight
 * semantic levels under a radically different visual posture.
 */

import type {
  SemanticSurfaceRole,
  SemanticSurfaceRoleTokens,
} from "@/foundation/contracts/kernel/tokens/materials";

